 kyoto_tower_transfer:[0],inari_transfer:[1],luggage_pickup:[2],osaka_transfer:[3,4],usj_transfer:[0,1],
 castle_transfer:[0],castle_station_walk:[1],nara_transfer:[1],nara_return_train:[2],nara_day_return:[4],
